impl<DT: Dispatch> FCClientRequestResponseGhost<DT> {
    pub open spec fn enqueue_op_pre(
        &self,
        tid: nat,
        op: DT::WriteOperation,
        batch_cell: CellId,
        fc_inst: FlatCombiner::Instance,
        inst: UnboundedLog::Instance<DT>,
